unitsize(0.5 cm);

pair A = (4 - sqrt(3),-1 - 4*sqrt(3)), B = (-8,2);

draw((-8,0)--(8,0));
draw((0,-8)--(0,3));
draw((0,0)--A,dashed);
draw((0,0)--B,dashed);

dot("$4 - \sqrt{3} + (-1 - 4 \sqrt{3})i$", A, S);
dot("$-8 + 2i$", B, W);
[/asy]

